import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import {
  type FormEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";
import { z } from "zod";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  getSighting,
  listRecentSightings,
  saveSighting,
  updateSightingDoneness,
} from "@/lib/sighting-functions";
import {
  type CreateSighting,
  type CreateSightingInput,
  createSightingInputSchema,
  DONENESS_FAILURE_MESSAGE,
  DONENESS_VALUES,
  type GetSighting,
  type ListRecentSightings,
  RECENT_SIGHTINGS_FAILURE_MESSAGE,
  SAVE_FAILURE_MESSAGE,
  type Sighting,
  type UpdateSightingDoneness,
} from "@/lib/sightings";

export const Route = createFileRoute("/")({
  component: CaptureRoute,
  validateSearch: z.object({
    completion: z.coerce.number().int().positive().optional(),
  }),
});

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
type LabelTime = {
  labelDate: string;
  labelTime: string;
};

const getCurrentDeviceTime = (): Date => new Date();
const LABEL_TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;
const STORE_OPENING_MINUTE = 9 * 60;
const STORE_CLOSING_MINUTE = 20 * 60;

function padTimePart(value: number): string {
  return value.toString().padStart(2, "0");
}

function getDeviceLabelTime(date: Date): LabelTime {
  return {
    labelDate: `${date.getFullYear()}-${padTimePart(date.getMonth() + 1)}-${padTimePart(date.getDate())}`,
    labelTime: `${padTimePart(date.getHours())}:${padTimePart(date.getMinutes())}`,
  };
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = LABEL_TIME_PATTERN.exec(labelTime);
  if (!match) {
    return undefined;
  }

  return Number(match[1]) * 60 + Number(match[2]);
}

function isOutsideStoreHours(labelMinute: number | undefined): boolean {
  return (
    labelMinute !== undefined &&
    (labelMinute < STORE_OPENING_MINUTE || labelMinute > STORE_CLOSING_MINUTE)
  );
}

function formatSavedLabelTime(sighting: Sighting): string {
  const date = new Date(`${sighting.labelDate}T12:00:00`);
  const hour = Math.floor(sighting.labelMinute / 60);
  const minute = sighting.labelMinute % 60;
  const time = new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    minute: "2-digit",
  }).format(new Date(2000, 0, 1, hour, minute));
  const formattedDate = new Intl.DateTimeFormat("en-US", {
    day: "numeric",
    month: "long",
    year: "numeric",
  }).format(date);

  return `Saved label time for ${formattedDate} at ${time}.`;
}

function formatRecentSighting(sighting: Sighting): string {
  return formatSavedLabelTime(sighting).replace("Saved label time for ", "");
}

function CaptureRoute(): ReactNode {
  const { completion } = Route.useSearch();
  const navigate = useNavigate();
  const get = useServerFn(getSighting);
  const listRecent = useServerFn(listRecentSightings);
  const save = useServerFn(saveSighting);
  const updateDoneness = useServerFn(updateSightingDoneness);
  const saveSightingFromRoute = useCallback<CreateSighting>(
    async (input) => {
      return await save({ data: input });
    },
    [save]
  );
  const updateSightingDonenessFromRoute = useCallback<UpdateSightingDoneness>(
    async (input) => {
      return await updateDoneness({ data: input });
    },
    [updateDoneness]
  );
  const getSightingFromRoute = useCallback<GetSighting>(
    async (id) => {
      return await get({ data: id });
    },
    [get]
  );
  const listRecentSightingsFromRoute =
    useCallback<ListRecentSightings>(async () => {
      return await listRecent();
    }, [listRecent]);

  return (
    <CaptureForm
      getSighting={getSightingFromRoute}
      initialCompletionId={completion}
      listRecentSightings={listRecentSightingsFromRoute}
      onOpenCompletionCorrection={async (id) => {
        await navigate({
          params: { sightingId: id.toString() },
          search: { from: "completion" },
          to: "/sightings/$sightingId",
        });
      }}
      onOpenRecentCorrection={async (id) => {
        await navigate({
          params: { sightingId: id.toString() },
          search: { from: "capture" },
          to: "/sightings/$sightingId",
        });
      }}
      saveSighting={saveSightingFromRoute}
      updateSightingDoneness={updateSightingDonenessFromRoute}
    />
  );
}

export function CapturePage(): ReactNode {
  const save = useServerFn(saveSighting);
  const updateDoneness = useServerFn(updateSightingDoneness);
  const saveSightingFromRoute = useCallback<CreateSighting>(
    async (input) => {
      return await save({ data: input });
    },
    [save]
  );
  const updateSightingDonenessFromRoute = useCallback<UpdateSightingDoneness>(
    async (input) => {
      return await updateDoneness({ data: input });
    },
    [updateDoneness]
  );

  return (
    <CaptureForm
      saveSighting={saveSightingFromRoute}
      updateSightingDoneness={updateSightingDonenessFromRoute}
    />
  );
}

export function CaptureForm({
  getSighting,
  initialCompletionId,
  listRecentSightings,
  now = getCurrentDeviceTime,
  onOpenCompletionCorrection,
  onOpenRecentCorrection,
  saveSighting,
  updateSightingDoneness,
}: Readonly<{
  getSighting?: GetSighting;
  initialCompletionId?: number;
  listRecentSightings?: ListRecentSightings;
  now?: () => Date;
  onOpenCompletionCorrection?: (id: number) => void;
  onOpenRecentCorrection?: (id: number) => void;
  saveSighting: CreateSighting;
  updateSightingDoneness?: UpdateSightingDoneness;
}>): ReactNode {
  const [labelTime, setLabelTime] = useState<LabelTime>();
  const [errorMessage, setErrorMessage] = useState<string>();
  const [isSaving, setIsSaving] = useState(false);
  const [recentErrorMessage, setRecentErrorMessage] = useState<string>();
  const [recentRefreshKey, setRecentRefreshKey] = useState(0);
  const [recentSightings, setRecentSightings] = useState<Sighting[]>();
  const [savedSighting, setSavedSighting] = useState<Sighting>();

  useEffect(() => {
    setLabelTime(getDeviceLabelTime(now()));
  }, [now]);

  useEffect(() => {
    if (!listRecentSightings) {
      return;
    }

    let active = true;
    if (recentRefreshKey > 0) {
      setRecentSightings(undefined);
    }
    const loadRecentSightings = async (): Promise<void> => {
      try {
        const result = await listRecentSightings();
        if (!active) {
          return;
        }

        if (!result.ok) {
          setRecentErrorMessage(result.message);
          return;
        }

        setRecentErrorMessage(undefined);
        setRecentSightings(result.sightings);
      } catch {
        if (active) {
          setRecentErrorMessage(RECENT_SIGHTINGS_FAILURE_MESSAGE);
        }
      }
    };

    loadRecentSightings().catch(() => {
      if (active) {
        setRecentErrorMessage(RECENT_SIGHTINGS_FAILURE_MESSAGE);
      }
    });
    return () => {
      active = false;
    };
  }, [listRecentSightings, recentRefreshKey]);

  useEffect(() => {
    if (!(initialCompletionId && getSighting)) {
      return;
    }

    let active = true;
    const loadCompletion = async (): Promise<void> => {
      try {
        const result = await getSighting(initialCompletionId);
        if (!active) {
          return;
        }

        if (result.ok) {
          setSavedSighting(result.sighting);
          return;
        }

        setErrorMessage(result.message);
      } catch {
        if (active) {
          setErrorMessage(RECENT_SIGHTINGS_FAILURE_MESSAGE);
        }
      }
    };

    loadCompletion().catch(() => {
      if (active) {
        setErrorMessage(RECENT_SIGHTINGS_FAILURE_MESSAGE);
      }
    });
    return () => {
      active = false;
    };
  }, [getSighting, initialCompletionId]);

  if (savedSighting && updateSightingDoneness) {
    return (
      <SightingCompletion
        onDone={() => {
          setErrorMessage(undefined);
          setLabelTime(getDeviceLabelTime(now()));
          setRecentRefreshKey((refreshKey) => refreshKey + 1);
          setSavedSighting(undefined);
        }}
        onOpenCorrection={onOpenCompletionCorrection}
        sighting={savedSighting}
        updateSightingDoneness={updateSightingDoneness}
      />
    );
  }

  if (!labelTime) {
    return (
      <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
        <header className="mb-8">
          <p className="font-medium text-muted-foreground text-sm">
            Chicken Tracking
          </p>
          <h1 className="mt-2 font-semibold text-4xl tracking-tight">
            Capture
          </h1>
          <p className="mt-2 text-muted-foreground">
            Record the label time exactly as printed.
          </p>
        </header>
        <Card aria-busy="true">
          <CardHeader>
            <CardTitle>Label time</CardTitle>
          </CardHeader>
          <CardContent>
            <output aria-live="polite">Preparing capture form…</output>
          </CardContent>
        </Card>
      </div>
    );
  }

  const labelMinute = labelTimeToMinute(labelTime.labelTime);
  const outsideStoreHours = isOutsideStoreHours(labelMinute);

  const handleSave = async (): Promise<void> => {
    if (isSaving) {
      return;
    }

    if (labelMinute === undefined) {
      setErrorMessage("Enter a complete clock time.");
      return;
    }

    const input: CreateSightingInput = {
      labelDate: labelTime.labelDate,
      labelMinute,
    };
    const validation = createSightingInputSchema.safeParse(input);
    if (!validation.success) {
      setErrorMessage("Enter a complete real date.");
      return;
    }

    setErrorMessage(undefined);
    setIsSaving(true);
    try {
      const result = await saveSighting(validation.data);

      if (!result.ok) {
        setErrorMessage(result.message);
        return;
      }

      setSavedSighting(result.sighting);
    } catch {
      setErrorMessage(SAVE_FAILURE_MESSAGE);
    } finally {
      setIsSaving(false);
    }
  };

  const handleSubmit = async (
    event: FormEvent<HTMLFormElement>
  ): Promise<void> => {
    event.preventDefault();
    await handleSave();
  };

  return (
    <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1 className="mt-2 font-semibold text-4xl tracking-tight">Capture</h1>
        <p className="mt-2 text-muted-foreground">
          Record the label time exactly as printed.
        </p>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>Label time</CardTitle>
        </CardHeader>
        <CardContent>
          <form
            aria-label="Capture label time"
            className="grid gap-6"
            noValidate
            onSubmit={handleSubmit}
          >
            <div className="grid gap-2">
              <Label htmlFor="label-time">Label time</Label>
              <Input
                aria-describedby={
                  outsideStoreHours ? "store-hours-warning" : undefined
                }
                className="h-16 text-3xl"
                id="label-time"
                onChange={(event) => {
                  setLabelTime((current) => {
                    if (!current) {
                      return current;
                    }

                    return { ...current, labelTime: event.target.value };
                  });
                }}
                required
                type="time"
                value={labelTime.labelTime}
              />
              {outsideStoreHours ? (
                <p
                  className="text-sm text-warning-foreground"
                  id="store-hours-warning"
                >
                  Outside store hours
                </p>
              ) : null}
            </div>
            <div className="grid gap-2">
              <Label htmlFor="label-date">Label date</Label>
              <Input
                id="label-date"
                onChange={(event) => {
                  setLabelTime((current) => {
                    if (!current) {
                      return current;
                    }

                    return { ...current, labelDate: event.target.value };
                  });
                }}
                required
                type="date"
                value={labelTime.labelDate}
              />
            </div>
            {errorMessage ? (
              <p
                aria-live="assertive"
                className="text-destructive text-sm"
                role="alert"
              >
                {errorMessage}
              </p>
            ) : null}
            {isSaving ? (
              <output aria-live="polite">Saving label time…</output>
            ) : null}
            <Button
              className="h-12 text-base"
              disabled={isSaving}
              type="submit"
            >
              Save label time
            </Button>
          </form>
        </CardContent>
      </Card>
      {listRecentSightings ? (
        <RecentSightings
          errorMessage={recentErrorMessage}
          onOpenCorrection={onOpenRecentCorrection}
          sightings={recentSightings}
        />
      ) : null}
    </div>
  );
}

function RecentSightings({
  errorMessage,
  onOpenCorrection,
  sightings,
}: Readonly<{
  errorMessage?: string;
  onOpenCorrection?: (id: number) => void;
  sightings?: Sighting[];
}>): ReactNode {
  return (
    <section aria-labelledby="recent-sightings-heading" className="mt-8">
      <h2
        className="font-semibold text-2xl tracking-tight"
        id="recent-sightings-heading"
      >
        Recent Sightings
      </h2>
      {errorMessage ? (
        <p className="mt-3 text-destructive text-sm" role="alert">
          {errorMessage}
        </p>
      ) : null}
      {errorMessage || sightings ? null : (
        <output
          aria-live="polite"
          className="mt-3 text-muted-foreground text-sm"
        >
          Loading recent sightings…
        </output>
      )}
      {sightings?.length === 0 ? (
        <p className="mt-3 text-muted-foreground text-sm">No sightings yet.</p>
      ) : null}
      {sightings && sightings.length > 0 ? (
        <ul className="mt-3 grid gap-3">
          {sightings.slice(0, 3).map((sighting) => (
            <li key={sighting.id}>
              <Button
                className="h-auto min-h-12 w-full justify-start whitespace-normal py-3 text-left text-base"
                onClick={() => onOpenCorrection?.(sighting.id)}
                type="button"
                variant="outline"
              >
                {formatRecentSighting(sighting)}
              </Button>
            </li>
          ))}
        </ul>
      ) : null}
    </section>
  );
}

function SightingCompletion({
  onDone,
  onOpenCorrection,
  sighting,
  updateSightingDoneness,
}: Readonly<{
  onDone: () => void;
  onOpenCorrection?: (id: number) => void;
  sighting: Sighting;
  updateSightingDoneness: UpdateSightingDoneness;
}>): ReactNode {
  const completionHeadingRef = useRef<HTMLHeadingElement>(null);
  const [currentSighting, setCurrentSighting] = useState(sighting);
  const [errorMessage, setErrorMessage] = useState<string>();
  const [isUpdating, setIsUpdating] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string>();

  useEffect(() => {
    completionHeadingRef.current?.focus();
  }, []);

  const saveDoneness = async (
    doneness: Sighting["doneness"]
  ): Promise<void> => {
    if (isUpdating || doneness === currentSighting.doneness) {
      return;
    }

    setErrorMessage(undefined);
    setSuccessMessage(undefined);
    setIsUpdating(true);
    try {
      const result = await updateSightingDoneness({
        doneness,
        id: currentSighting.id,
      });

      if (!result.ok) {
        if (result.kind === "not-found") {
          setErrorMessage(`${result.message} Start a new Capture.`);
          return;
        }

        setErrorMessage(`${result.message} The label time remains saved.`);
        return;
      }

      setCurrentSighting(result.sighting);
      setSuccessMessage(
        doneness === null
          ? "Doneness cleared."
          : `Doneness saved as ${doneness}.`
      );
    } catch {
      setErrorMessage(
        `${DONENESS_FAILURE_MESSAGE} The label time remains saved.`
      );
    } finally {
      setIsUpdating(false);
    }
  };

  return (
    <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1
          className="mt-2 font-semibold text-4xl tracking-tight"
          ref={completionHeadingRef}
          tabIndex={-1}
        >
          Sighting saved
        </h1>
        <p className="mt-2 text-muted-foreground">
          {formatSavedLabelTime(currentSighting)}
        </p>
      </header>
      <Card>
        <CardHeader>
          <CardTitle>Optional doneness</CardTitle>
        </CardHeader>
        <CardContent className="grid gap-6">
          <p className="text-muted-foreground text-sm">
            Record how the chicken looked, or leave this unrecorded.
          </p>
          <fieldset className="grid gap-3">
            <legend className="sr-only">Doneness</legend>
            {DONENESS_VALUES.map((doneness) => (
              <Button
                aria-pressed={currentSighting.doneness === doneness}
                className="h-12 justify-start text-base capitalize"
                disabled={isUpdating}
                key={doneness}
                onClick={() => saveDoneness(doneness)}
                type="button"
                variant={
                  currentSighting.doneness === doneness ? "default" : "outline"
                }
              >
                {`${doneness[0]?.toUpperCase()}${doneness.slice(1)}`}
              </Button>
            ))}
            <Button
              aria-pressed={currentSighting.doneness === null}
              className="h-12 justify-start text-base"
              disabled={isUpdating || currentSighting.doneness === null}
              onClick={() => saveDoneness(null)}
              type="button"
              variant="outline"
            >
              Clear doneness
            </Button>
          </fieldset>
          {isUpdating ? (
            <output aria-live="polite">Saving doneness…</output>
          ) : null}
          {successMessage ? (
            <output aria-atomic="true" aria-live="polite">
              {successMessage}
            </output>
          ) : null}
          {errorMessage ? (
            <p
              aria-live="assertive"
              className="text-destructive text-sm"
              role="alert"
            >
              {errorMessage}
            </p>
          ) : null}
          <Button
            className="h-12 text-base"
            disabled={isUpdating}
            onClick={onDone}
            type="button"
          >
            Done
          </Button>
          <Button
            className="h-12 text-base"
            disabled={isUpdating}
            onClick={() => onOpenCorrection?.(currentSighting.id)}
            type="button"
            variant="outline"
          >
            Correct this sighting
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import {
  type FormEvent,
  type ReactNode,
  useEffect,
  useRef,
  useState,
} from "react";
import { z } from "zod";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  correctSighting,
  deleteSighting,
  getSighting,
} from "@/lib/sighting-functions";
import {
  type CorrectSighting,
  correctSightingInputSchema,
  DELETE_FAILURE_MESSAGE,
  type DeleteSighting,
  DONENESS_VALUES,
  type GetSighting,
  RECENT_SIGHTINGS_FAILURE_MESSAGE,
  SIGHTING_NOT_FOUND_MESSAGE,
  type Sighting,
} from "@/lib/sightings";

export const Route = createFileRoute("/sightings/$sightingId")({
  component: CorrectionRoute,
  validateSearch: z.object({
    from: z.enum(["capture", "completion"]).catch("capture"),
  }),
});

const LABEL_TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;

// biome-ignore lint/style/useConsistentTypeDefinitions: AGENTS.md prefers types unless extending.
type CorrectionFields = {
  doneness: Sighting["doneness"];
  labelDate: string;
  labelTime: string;
};

function labelMinuteToTime(labelMinute: number): string {
  const hour = Math.floor(labelMinute / 60);
  const minute = labelMinute % 60;

  return `${hour.toString().padStart(2, "0")}:${minute.toString().padStart(2, "0")}`;
}

function labelTimeToMinute(labelTime: string): number | undefined {
  const match = LABEL_TIME_PATTERN.exec(labelTime);
  if (!match) {
    return undefined;
  }

  return Number(match[1]) * 60 + Number(match[2]);
}

function correctionFieldsFromSighting(sighting: Sighting): CorrectionFields {
  return {
    doneness: sighting.doneness,
    labelDate: sighting.labelDate,
    labelTime: labelMinuteToTime(sighting.labelMinute),
  };
}

function getFocusTarget(isLoading: boolean, isNotFound: boolean): string {
  if (isLoading) {
    return "loading";
  }

  return isNotFound ? "not-found" : "editor";
}

export function CorrectionRoute(): ReactNode {
  const { sightingId } = Route.useParams();
  const { from } = Route.useSearch();
  const navigate = useNavigate();
  const correct = useServerFn(correctSighting);
  const remove = useServerFn(deleteSighting);
  const get = useServerFn(getSighting);
  const id = Number(sightingId);
  const returnToOrigin = async (
    preserveCompletion: boolean,
    sighting?: Sighting
  ): Promise<void> => {
    await navigate({
      search:
        preserveCompletion && from === "completion"
          ? { completion: sighting?.id ?? id }
          : {},
      to: "/",
    });
  };

  return (
    <CorrectionEditor
      correctSighting={async (input) => await correct({ data: input })}
      deleteSighting={async (deleteId) => await remove({ data: deleteId })}
      getSighting={async (getId) => await get({ data: getId })}
      id={id}
      onCancel={async () => await returnToOrigin(true)}
      onDeleted={async () => await returnToOrigin(false)}
      onNotFoundReturn={async () => await returnToOrigin(false)}
      onSaved={async (sighting) => await returnToOrigin(true, sighting)}
    />
  );
}

export function CorrectionEditor({
  correctSighting,
  deleteSighting,
  getSighting,
  id,
  onCancel,
  onDeleted,
  onNotFoundReturn,
  onSaved,
}: Readonly<{
  correctSighting: CorrectSighting;
  deleteSighting: DeleteSighting;
  getSighting: GetSighting;
  id: number;
  onCancel: () => Promise<void>;
  onDeleted: () => Promise<void>;
  onNotFoundReturn: () => Promise<void>;
  onSaved: (sighting: Sighting) => Promise<void>;
}>): ReactNode {
  const headingRef = useRef<HTMLHeadingElement>(null);
  const confirmationRef = useRef<HTMLHeadingElement>(null);
  const [fields, setFields] = useState<CorrectionFields>();
  const [errorMessage, setErrorMessage] = useState<string>();
  const [isConfirmingDeletion, setIsConfirmingDeletion] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isNotFound, setIsNotFound] = useState(false);
  const [loadAttempt, setLoadAttempt] = useState(0);

  const focusTarget = getFocusTarget(isLoading, isNotFound);

  useEffect(() => {
    if (focusTarget !== "loading") {
      headingRef.current?.focus();
    }
  }, [focusTarget]);

  useEffect(() => {
    if (!Number.isInteger(id) || id < 1) {
      setIsLoading(false);
      setIsNotFound(true);
      return;
    }

    let active = true;
    if (loadAttempt > 0) {
      setFields(undefined);
      setIsNotFound(false);
    }
    const markLoadUnavailable = (): void => {
      if (active) {
        setErrorMessage(RECENT_SIGHTINGS_FAILURE_MESSAGE);
      }
    };
    const loadSighting = async (): Promise<void> => {
      setIsLoading(true);
      setErrorMessage(undefined);
      try {
        const result = await getSighting(id);
        if (!active) {
          return;
        }

        if (!result.ok) {
          setIsNotFound(result.kind === "not-found");
          setErrorMessage(
            result.kind === "not-found" ? undefined : result.message
          );
          return;
        }

        setFields(correctionFieldsFromSighting(result.sighting));
        setIsNotFound(false);
      } catch {
        markLoadUnavailable();
      } finally {
        if (active) {
          setIsLoading(false);
        }
      }
    };

    loadSighting().catch(markLoadUnavailable);
    return () => {
      active = false;
    };
  }, [getSighting, id, loadAttempt]);

  const updateFields = (next: Partial<CorrectionFields>): void => {
    setFields((current) => (current ? { ...current, ...next } : current));
  };

  const saveCorrection = async (): Promise<void> => {
    if (!fields || isSaving || isDeleting) {
      return;
    }

    const labelMinute = labelTimeToMinute(fields.labelTime);
    if (labelMinute === undefined) {
      setErrorMessage("Enter a complete clock time.");
      return;
    }

    const validation = correctSightingInputSchema.safeParse({
      doneness: fields.doneness,
      id,
      labelDate: fields.labelDate,
      labelMinute,
    });
    if (!validation.success) {
      setErrorMessage("Enter a complete real date.");
      return;
    }

    setErrorMessage(undefined);
    setIsSaving(true);
    try {
      const result = await correctSighting(validation.data);
      if (!result.ok) {
        if (result.kind === "not-found") {
          setIsNotFound(true);
          return;
        }

        setErrorMessage(result.message);
        return;
      }

      await onSaved(result.sighting);
    } catch {
      setErrorMessage("Unable to save this correction. Try again.");
    } finally {
      setIsSaving(false);
    }
  };

  const confirmDeletion = async (): Promise<void> => {
    if (isDeleting || isSaving) {
      return;
    }

    setErrorMessage(undefined);
    setIsDeleting(true);
    try {
      const result = await deleteSighting(id);
      if (!result.ok) {
        if (result.kind === "not-found") {
          setIsNotFound(true);
          setIsConfirmingDeletion(false);
          return;
        }

        setErrorMessage(result.message);
        return;
      }

      await onDeleted();
    } catch {
      setErrorMessage(DELETE_FAILURE_MESSAGE);
    } finally {
      setIsDeleting(false);
    }
  };

  const handleSubmit = async (
    event: FormEvent<HTMLFormElement>
  ): Promise<void> => {
    event.preventDefault();
    await saveCorrection();
  };

  const returnWithoutSaving = async (
    returnToOrigin: () => Promise<void>
  ): Promise<void> => {
    try {
      await returnToOrigin();
    } catch {
      setErrorMessage("Unable to return to Capture. Try again.");
    }
  };

  if (isLoading) {
    return (
      <CorrectionFrame heading="Correct sighting">
        Loading sighting…
      </CorrectionFrame>
    );
  }

  if (isNotFound) {
    return (
      <CorrectionFrame heading="Sighting not found" headingRef={headingRef}>
        <p className="text-muted-foreground">{SIGHTING_NOT_FOUND_MESSAGE}</p>
        <Button
          className="mt-6 h-12 text-base"
          onClick={async () => await returnWithoutSaving(onNotFoundReturn)}
          type="button"
        >
          Return to Capture
        </Button>
      </CorrectionFrame>
    );
  }

  if (!fields) {
    return (
      <CorrectionFrame heading="Correct sighting" headingRef={headingRef}>
        <p className="text-destructive" role="alert">
          {errorMessage ?? RECENT_SIGHTINGS_FAILURE_MESSAGE}
        </p>
        <Button
          className="mt-6 h-12 text-base"
          onClick={() => setLoadAttempt((attempt) => attempt + 1)}
          type="button"
        >
          Try again
        </Button>
        <Button
          className="mt-3 h-12 text-base"
          onClick={async () => await returnWithoutSaving(onCancel)}
          type="button"
          variant="outline"
        >
          Cancel
        </Button>
      </CorrectionFrame>
    );
  }

  return (
    <CorrectionFrame heading="Correct sighting" headingRef={headingRef}>
      <Card>
        <CardHeader>
          <CardTitle>Label facts</CardTitle>
        </CardHeader>
        <CardContent>
          <form className="grid gap-6" noValidate onSubmit={handleSubmit}>
            <div className="grid gap-2">
              <Label htmlFor="correction-label-time">Label time</Label>
              <Input
                className="h-16 text-3xl"
                id="correction-label-time"
                onChange={(event) =>
                  updateFields({ labelTime: event.target.value })
                }
                required
                type="time"
                value={fields.labelTime}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="correction-label-date">Label date</Label>
              <Input
                id="correction-label-date"
                onChange={(event) =>
                  updateFields({ labelDate: event.target.value })
                }
                required
                type="date"
                value={fields.labelDate}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="correction-doneness">Doneness</Label>
              <select
                className="h-12 rounded-md border bg-background px-3"
                id="correction-doneness"
                onChange={(event) =>
                  updateFields({
                    doneness:
                      event.target.value === ""
                        ? null
                        : (event.target.value as Sighting["doneness"]),
                  })
                }
                value={fields.doneness ?? ""}
              >
                <option value="">Not recorded</option>
                {DONENESS_VALUES.map((doneness) => (
                  <option key={doneness} value={doneness}>
                    {`${doneness[0]?.toUpperCase()}${doneness.slice(1)}`}
                  </option>
                ))}
              </select>
            </div>
            {errorMessage ? (
              <p className="text-destructive text-sm" role="alert">
                {errorMessage}
              </p>
            ) : null}
            {isSaving ? (
              <output aria-live="polite">Saving correction…</output>
            ) : null}
            <Button
              className="h-12 text-base"
              disabled={isSaving || isDeleting}
              type="submit"
            >
              Save correction
            </Button>
            <Button
              className="h-12 text-base"
              disabled={isSaving || isDeleting}
              onClick={onCancel}
              type="button"
              variant="outline"
            >
              Cancel
            </Button>
          </form>
        </CardContent>
      </Card>
      <Dialog
        onOpenChange={setIsConfirmingDeletion}
        open={isConfirmingDeletion}
      >
        <section
          aria-labelledby="delete-heading"
          className="mt-8 border-destructive border-t pt-6"
        >
          <h2 className="font-semibold text-xl" id="delete-heading">
            Delete this sighting
          </h2>
          <p className="mt-2 text-muted-foreground text-sm">
            Deletion permanently removes this sighting.
          </p>
          <DialogTrigger asChild>
            <Button
              className="mt-4 h-12 text-base"
              disabled={isSaving || isDeleting}
              type="button"
              variant="destructive"
            >
              Delete sighting
            </Button>
          </DialogTrigger>
        </section>
        <DialogContent
          onOpenAutoFocus={(event) => {
            event.preventDefault();
            confirmationRef.current?.focus();
          }}
          showCloseButton={false}
        >
          <DialogHeader>
            <DialogTitle ref={confirmationRef} tabIndex={-1}>
              Permanently delete this sighting?
            </DialogTitle>
            <DialogDescription>This action cannot be undone.</DialogDescription>
          </DialogHeader>
          {errorMessage ? (
            <p className="text-destructive text-sm" role="alert">
              {errorMessage}
            </p>
          ) : null}
          {isDeleting ? (
            <output aria-live="polite">Deleting sighting…</output>
          ) : null}
          <DialogFooter>
            <Button
              disabled={isDeleting}
              onClick={confirmDeletion}
              type="button"
              variant="destructive"
            >
              Permanently delete
            </Button>
            <DialogClose asChild>
              <Button disabled={isDeleting} type="button" variant="outline">
                Keep sighting
              </Button>
            </DialogClose>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </CorrectionFrame>
  );
}

function CorrectionFrame({
  children,
  heading,
  headingRef,
}: Readonly<{
  children: ReactNode;
  heading: string;
  headingRef?: React.RefObject<HTMLHeadingElement | null>;
}>): ReactNode {
  return (
    <div className="mx-auto flex min-h-screen w-full max-w-md flex-col px-4 py-8">
      <header className="mb-8">
        <p className="font-medium text-muted-foreground text-sm">
          Chicken Tracking
        </p>
        <h1
          className="mt-2 font-semibold text-4xl tracking-tight"
          ref={headingRef}
          tabIndex={-1}
        >
          {heading}
        </h1>
      </header>
      {children}
    </div>
  );
}
